package com.onebytelabs.zlplay;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.io.*;import com.onebytelabs.zlplay.audio.*;import com.onebytelabs.zlplay.project.*;
public final class QueueSmoke {
 static Object get(Object o,String key)throws Exception{Field f=o.getClass().getDeclaredField(key);f.setAccessible(true);return f.get(o);}static void set(Object o,String key,Object value)throws Exception{Field f=o.getClass().getDeclaredField(key);f.setAccessible(true);f.set(o,value);}static Object call(Object o,String name,Class<?>[] types,Object...args){try{Method m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(o,args);}catch(Exception e){throw new RuntimeException(e);}}static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static Bundle run(Instrumentation test)throws Exception{Context base=test.getTargetContext();Context sandbox=new ContextWrapper(base){public SharedPreferences getSharedPreferences(String name,int mode){return base.getSharedPreferences("queue-test-"+name,mode);}public File getFilesDir(){File d=new File(base.getCacheDir(),"queue-test");d.mkdirs();return d;}};sandbox.getSharedPreferences("android-library",0).edit().clear().commit();RepertoireLibrary lib=new RepertoireLibrary(sandbox);lib.remember("tree-a","a.zlset","A");lib.remember("tree-b","b.zlset","B");lib.remember("tree-a","a.zlset","A renamed");check(new RepertoireLibrary(sandbox).entries().length()==2,"Library persists and deduplicates imports");SetlistSpec list=new SetlistSpec();list.title="Queue fixture";for(int i=0;i<5;i++){SetlistSpec.Song song=new SetlistSpec.Song();song.id="id"+i;song.name="Song "+i+" - Artist";song.folder="Song"+i;song.project="Song"+i+"/song.rpp";song.originalKey=song.tonalKey="D";list.songs.add(song);}lib.saveOrder("a",java.util.Arrays.asList(list.songs.get(2),list.songs.get(0),list.songs.get(1)));lib.applyOrder("a",list.songs);check(list.songs.get(0).id.equals("id2")&&list.songs.size()==5,"Saved order restores and appends new songs");Bitmap art=Bitmap.createBitmap(128,128,Bitmap.Config.ARGB_8888);art.eraseColor(0xff8c4ee7);File image=new File(sandbox.getFilesDir(),"synthetic.png");try(FileOutputStream out=new FileOutputStream(image)){art.compress(Bitmap.CompressFormat.PNG,100,out);}art.recycle();Bitmap imported=lib.importCover("cover",Uri.fromFile(image));check(imported.getWidth()==128&&lib.coverFile("cover").isFile(),"Cover is imported privately");File invalid=new File(sandbox.getFilesDir(),"bad.png");try(FileOutputStream out=new FileOutputStream(invalid)){out.write(1);}try{lib.importCover("cover",Uri.fromFile(invalid));throw new AssertionError("Invalid cover accepted");}catch(IOException expected){}check(BitmapFactory.decodeFile(lib.coverFile("cover").toString())!=null,"Invalid cover preserves old image");
 MainActivity screen=(MainActivity)test.startActivitySync(new Intent(base,MainActivity.class).putExtra("com.onebytelabs.zlplay.SKIP_RESTORE_TEST",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{test.waitForIdleSync();DemoMixer mixer=(DemoMixer)get(screen,"mixer");test.runOnMainSync(()->{try{set(screen,"library",lib);set(screen,"setlist",list);set(screen,"setlistFolder",new ProjectFolder(Uri.parse("content://queue-fixture")));set(screen,"setlistFile","a.zlset");set(screen,"setlistIndex",1);call(screen,"renderSetlist",new Class<?>[]{});}catch(Exception e){throw new RuntimeException(e);}});LinearLayout cards=(LinearLayout)get(screen,"songCards");check(((Button)cards.getChildAt(0)).getText().toString().startsWith("Song"),"Song card has no number prefix");check(((Button)cards.getChildAt(0)).getCompoundDrawables()[0]!=null,"Song card includes cover placeholder");SetlistSpec.Song playing=list.songs.get(1);test.runOnMainSync(()->screen.moveSong(0,4));check(list.songs.get(3).id.equals("id2")&&list.songs.get((Integer)get(screen,"setlistIndex"))==playing,"Reorder preserves currently loaded song");
 test.runOnMainSync(()->call(screen,"showRepertoire",new Class<?>[]{}));test.waitForIdleSync();Thread.sleep(400);Dialog repertoire=(Dialog)get(screen,"repertoireDialog");View source=findDescription(repertoire.getWindow().getDecorView(),screen.getString(R.string.reorder_help)+" "+list.songs.get(0).name),destination=findDescription(repertoire.getWindow().getDecorView(),screen.getString(R.string.reorder_help)+" "+list.songs.get(2).name);check(source!=null&&destination!=null,"Draggable repertoire rows");SetlistSpec.Song dragged=list.songs.get(0);int[] sourcePos=new int[2],targetPos=new int[2];test.runOnMainSync(()->{source.getLocationOnScreen(sourcePos);destination.getLocationOnScreen(targetPos);});float x=sourcePos[0]+45*screen.getResources().getDisplayMetrics().density,y=sourcePos[1]+source.getHeight()/2f,end=targetPos[1]+destination.getHeight()*.8f;long down=SystemClock.uptimeMillis();touch(test,down,MotionEvent.ACTION_DOWN,x,y);Thread.sleep(ViewConfiguration.getLongPressTimeout()+350L);for(int move=1;move<=12;move++){touch(test,down,MotionEvent.ACTION_MOVE,x,y+(end-y)*move/12);Thread.sleep(20);}Thread.sleep(180);touch(test,down,MotionEvent.ACTION_UP,x,end);for(int wait=0;wait<30&&list.songs.indexOf(dragged)!=2;wait++){Thread.sleep(60);test.waitForIdleSync();}check(list.songs.indexOf(dragged)==2,"Real long-press drag reorders song: index="+list.songs.indexOf(dragged)+", fromY="+y+", endY="+end);test.runOnMainSync(()->{try{((Dialog)get(screen,"repertoireDialog")).dismiss();}catch(Exception e){throw new RuntimeException(e);}});
 ProjectSpec spec=new ProjectSpec();spec.bpm=120;spec.numerator=6;spec.denominator=8;spec.duration=90;test.runOnMainSync(()->{try{set(screen,"activeProject",spec);mixer.setBpm(120);}catch(Exception e){throw new RuntimeException(e);}});View wave=(View)get(screen,"waveform");check(Math.abs((Double)call(wave,"beatSeconds",new Class<?>[]{})-.25)<.0001,"Grid follows BPM and denominator");spec.numerator=4;spec.denominator=4;check(Math.abs((Double)call(wave,"beatSeconds",new Class<?>[]{})-.5)<.0001&&(Integer)call(wave,"beatsPerBar",new Class<?>[]{})==4,"4/4 projects use their own 4/4 grid");test.runOnMainSync(()->{try{set(wave,"viewStart",0.0);mixer.seek(44);mixer.play();call(wave,"followCursor",new Class<?>[]{});}catch(Exception e){throw new RuntimeException(e);}});double start=(Double)get(wave,"viewStart");check(start>0&&start<38,"Follow scroll advances partially, not a jump");test.runOnMainSync(mixer::pause);
 test.runOnMainSync(()->{PcmTrack[] stems=new PcmTrack[16];for(int i=0;i<stems.length;i++)stems[i]=new PcmTrack("Stem "+i,48000,1,new float[1]){public double duration(){return 90;}};mixer.load(stems);});test.runOnMainSync(()->call(screen,"showMixer",new Class<?>[]{}));test.waitForIdleSync();Dialog dialog=(Dialog)get(screen,"mixerDialog");FaderSeekBar pad=find(dialog.getWindow().getDecorView(),screen.getString(R.string.volume,screen.getString(R.string.pad)));FaderSeekBar master=find(dialog.getWindow().getDecorView(),screen.getString(R.string.volume,screen.getString(R.string.master_channel)));check(pad.getMax()==master.getMax()&&pad.getMax()>=200,"Pad unity position matches other faders");int original=master.getProgress();boolean[] accepted={true};test.runOnMainSync(()->{float off=master.getPaddingLeft()+2;MotionEvent offEvent=MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,off,master.getHeight()/2f,0);accepted[0]=master.onTouchEvent(offEvent);offEvent.recycle();});check(!accepted[0]&&master.getProgress()==original,"Off-thumb touch is available to mixer scroll");LinearLayout panel=(LinearLayout)get(screen,"mixerPanel");HorizontalScrollView mixerScroll=(HorizontalScrollView)panel.getChildAt(0);FaderSeekBar rail=find(dialog.getWindow().getDecorView(),screen.getString(R.string.volume,"Stem 3"));View area=(View)rail.getParent();int[] railPos=new int[2];test.runOnMainSync(()->area.getLocationOnScreen(railPos));float rx=railPos[0]+area.getWidth()/2f,ry=railPos[1]+area.getHeight()*.18f;float gainBefore=mixer.getGain(3);long swipe=SystemClock.uptimeMillis();touch(test,swipe,MotionEvent.ACTION_DOWN,rx,ry);for(int move=1;move<=12;move++){touch(test,swipe,MotionEvent.ACTION_MOVE,rx-250*move/12f,ry);Thread.sleep(18);}touch(test,swipe,MotionEvent.ACTION_UP,rx-250,ry);test.waitForIdleSync();check(mixerScroll.getScrollX()>30&&mixer.getGain(3)==gainBefore,"Real off-thumb mixer swipe scrolls without changing gain");Bundle result=new Bundle();result.putString("status","PASS: persistent repertoire catalog/order, private cover validation, cover cards/no numbering, current-song-safe reorder/real long-press drag, BPM/6-8 grid, smooth follow, Pad unity and real off-thumb mixer scroll");return result;}finally{test.runOnMainSync(screen::finish);sandbox.getSharedPreferences("android-library",0).edit().clear().commit();}}
 static void touch(Instrumentation test,long down,int action,float x,float y){MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);if(!test.getUiAutomation().injectInputEvent(event,true))throw new AssertionError("Drag event injection");event.recycle();}
 static View findDescription(View v,String title){if(v.getContentDescription()!=null&&title.contentEquals(v.getContentDescription()))return v;if(v instanceof android.view.ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=0;i<group.getChildCount();i++){View found=findDescription(group.getChildAt(i),title);if(found!=null)return found;}}return null;}
 static FaderSeekBar find(View v,String title){if(v instanceof FaderSeekBar&&title.contentEquals(v.getContentDescription()))return(FaderSeekBar)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){FaderSeekBar b=find(g.getChildAt(i),title);if(b!=null)return b;}}return null;}
}
